    <script>
        const products = [
            {id:1, name:'经典白衬衫', price:199, img:'', description:'柔软棉质，适合职场与日常。'},
            {id:2, name:'柔软针织衫', price:269, img:'', description:'轻盈保暖，颜色多样。'},
            {id:3, name:'商务西装裙', price:499, img:'', description:'修身剪裁，提升气质。'},
            {id:4, name:'休闲牛仔裤', price:259, img:'', description:'弹力面料，舒适随性。'},
