        const grid = document.getElementById('product-grid');
        products.forEach(p=>{
            const card = document.createElement('div');
            card.className='card';
            card.innerHTML=`
                <img alt="${p.name}" src="data:image/svg+xml;base64,${btoa('<svg xmlns="http://www.w3.org/2000/svg" width="300" height="200"><rect width="300" height="200" fill="#e0e0e0"/><text x="150" y="110" font-size="20" text-anchor="middle" fill="#999">图片</text></svg>')}">
